using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using UnityEngine;

[BurstCompile]
struct DamageJob : IJob
{
    [ReadOnly] public NativeArray<float> damage;   // was float[]
    [ReadOnly] public NativeArray<int> crits;      // was List<int>
    public NativeArray<float> total;

    public void Execute()
    {
        float sum = 0f;
        for (int i = 0; i < damage.Length; i++) sum += damage[i];
        for (int i = 0; i < crits.Length; i++) sum += damage[crits[i]];   // Length, not Count
        total[0] = sum;
        Debug.Log($"Total damage: {sum}");          // Burst formats it, no managed string
    }
}

