using System;
using System.Diagnostics;
using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;

[BurstCompile]
struct FillJob : IJob
{
    public NativeArray<float> buffer;
    public int count;
    public float value;

    public void Execute()
    {
        CheckCount(count, buffer.Length);   // compiled out of player builds
        for (int i = 0; i < count; i++) buffer[i] = value;
    }

    [Conditional("ENABLE_UNITY_COLLECTIONS_CHECKS")]
    static void CheckCount(int count, int length)
    {
        if (count < 0 || count > length)
            throw new ArgumentException("count is out of range");
    }
}

