interface IRule { float Apply(float x); }
struct DoubleRule : IRule { public float Apply(float x) => x * 2f; }

[BurstCompile]
struct ApplyJob<T> : IJob where T : struct, IRule
{
    public T rule;                       // a concrete struct: no boxing
    public NativeArray<float> data;
    public void Execute()
    {
        for (int i = 0; i < data.Length; i++) data[i] = rule.Apply(data[i]);
    }
}

IRule boxed = new DoubleRule();          // boxing: not allowed in Burst code

